-- Per-round beats + playback sync, and the full curated beat library.
-- Additive only: nothing is deleted, existing battles keep working.

-- Each freestyle remembers which beat it was recorded over (so a response
-- can use its own beat), how far the voice lags the beat (device audio
-- latency, used to line the two up on playback) and how long it runs.
alter table freestyles add column if not exists beat_id uuid references beats(id);
alter table freestyles add column if not exists beat_offset_ms integer not null default 0;
alter table freestyles add column if not exists duration_ms integer;

-- Old rounds were all recorded over the battle's beat.
update freestyles f set beat_id = b.beat_id
from battles b
where f.battle_id = b.id and f.beat_id is null;

